INSERT INTO interview_feedbacks (id, interview_round_id, reviewer_id, technical_score, communication_score, comment, recommendation, created_at) VALUES
    ('b71ec837-74aa-4352-8be0-bf2e24facc25', 'dc09246c-f1e7-4bde-92a6-ea3b2a9eeefc', '6d92183c-1eff-4ce5-9896-de3d1b9b364c', 78, 83, 'Ứng viên Đinh Văn Tuấn nắm chắc kiến thức nền tảng, giải quyết bài toán thực tế mạch lạc và giao tiếp tự tin.', 'HIRE', NOW() - interval '10 days'),
    ('1f858d11-ab56-4b46-b378-e0e775d93e5d', '024e04fd-3eb8-47ab-a2d8-71d12a046a42', '3670bafc-9fef-40b2-a8b2-9cbab0804253', 79, 84, 'Ứng viên Mai Thị Uyên nắm chắc kiến thức nền tảng, giải quyết bài toán thực tế mạch lạc và giao tiếp tự tin.', 'HIRE', NOW() - interval '9 days'),
