    ('fad4ae24-de20-470f-bc33-32a795408501', '1287a453-ed20-4b77-81b1-432882249ba9', '3670bafc-9fef-40b2-a8b2-9cbab0804253', 81, 86, 'Ứng viên Đào Thị Xuân nắm chắc kiến thức nền tảng, giải quyết bài toán thực tế mạch lạc và giao tiếp tự tin.', 'HIRE', NOW() - interval '7 days'),
